+                const isSelected = selectedStyles.some((s) => s.id === style.id);
+                return (
+                  <div
+                    key={style.id}
+                    className="flex-[0_0_200px] min-w-0"
+                  >
+                    <button
+                      onClick={() => toggleStyle(style)}
+                      className={`
+                        w-full rounded-xl overflow-hidden
+                        transition-all duration-300 bg-white shadow-md
+                        border-l-2 ${isSelected ? 'border-[var(--onboarding-primary)]' : 'border-transparent'}
+                      `}
+                    >
+                      {/* Style Image - Cropped to hide baked-in text at bottom */}
+                      <div className="w-full h-[280px] overflow-hidden">
+                        {style.imageUrl && !failedImages.has(style.id) ? (
+                          <img
+                            src={style.imageUrl}
+                            alt={`${style.name} style`}
+                            loading="lazy"
+                            onError={() => handleImageError(style.id)}
+                            className="w-full h-full object-cover object-top"
+                          />
+                        ) : (
